package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;
import static org.jlinalg.cli.AllcoolsPosteriorRequest.require;
import static org.jlinalg.cli.AllcoolsPosteriorCompute.map;

/** Complete input capture, owned original workflow and full saved numerical/binary replay. */
final class MerquryBundle {
    private MerquryBundle() { }
    static final String ACTION="Required action: inspect WARNINGS.md, OUTPUT-AUDIT.json and all original process logs. Require COMPLETED.json and merqury-tools --verify CAPTURE --scratch NEW_DIRECTORY with the exact producing JAR and unchanged bound Linux runtime. Missing or forbidden prerequisites give SKIP3 and skip dependent analysis; install only where permitted, then create a NEW binding. Changed data/runtime, malformed input, undefined requested rates, original child failure, incomplete plots, cancellation and resource failures give FAIL2 with no complete result. Preserve failed attempts and original inputs; correct the named cause and retry NEW paths. No paper parameters, homopolymer compression or author edition substitutions are inferred.";
    static Path producerPath()throws IOException {
        try {Path path=Path.of(MerquryBundle.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();if(!path.getFileName().toString().endsWith(".jar"))throw new MerquryRuntime.Unavailable("Retain and run the complete executable producing JAR; class-directory admission is unavailable");return path;}
        catch(java.net.URISyntaxException e){throw new IOException("Producing JAR identity unavailable",e);}
    }
    static Pin producer()throws IOException{return pin(producerPath(),1000000000L,()->{});}
    static Runnable bounded(MerquryRequest.Spec spec,Runnable cancellation) {
        long start=System.nanoTime();return ()->{cancellation.run();if(Thread.currentThread().isInterrupted()||(System.nanoTime()-start)/1000000>spec.capacity().wallMillis())throw new IllegalStateException("Merqury complete workflow wall limit/cancellation exceeded");};
    }
    static Path capture(Path supplied,MerquryRequest.Spec spec,Runnable cancellation)throws IOException {
        MerquryRuntime.platform();Runnable check=bounded(spec,cancellation);var runtime=MerquryRuntime.open(spec.runtime(),spec.edition(),check);Pin producer=producer();
        Path root=supplied.toAbsolutePath().normalize();require(root.equals(supplied.toAbsolutePath())&&root.getParent()!=null,"Use a NEW canonical capture directory");directory(root.getParent());require(!Files.exists(root,LinkOption.NOFOLLOW_LINKS),"Capture exists; use a NEW path");
        require(!root.startsWith(spec.runtime())&&!spec.runtime().startsWith(root)&&!root.startsWith(runtime.source()),"Capture must be separate from runtime and original source");
        var originals=new ArrayList<Map<String,Object>>();long inputBytes=0;int index=0;
        for(var input:spec.inputs()) {
            check.run();Path path=input.path();if(!Files.exists(path,LinkOption.NOFOLLOW_LINKS)||!Files.isReadable(path))throw new MerquryRuntime.Unavailable("Complete permitted input unavailable: "+path);
            require(!root.startsWith(path)&&!path.startsWith(root),"Capture and original input overlap");String staged;
            if(input.kind().equals("meryl"))staged=input.role()+".meryl";
            else if(input.kind().equals("fasta"))staged="asm"+input.role().substring("assembly".length())+(path.toString().endsWith(".gz")?".fasta.gz":".fasta");
            else staged=String.format(Locale.ROOT,"reads-%04d",++index)+suffix(path);
            Object identity;
            if(input.kind().equals("meryl")) {
                var tree=tree(path,spec.capacity().files(),spec.capacity().inputBytes(),spec.capacity().inputBytes(),check);require(!tree.isEmpty()&&tree.values().stream().allMatch(e->e.kind().equals("file")),"Complete unlinked original Meryl database required");identity=manifest(tree);for(var file:tree.values())inputBytes=Math.addExact(inputBytes,file.pin().bytes());
            }else {Pin p=pin(path,spec.capacity().inputBytes(),check);identity=map("bytes",p.bytes(),"sha256",p.sha256());inputBytes=Math.addExact(inputBytes,p.bytes());}
            require(inputBytes<=spec.capacity().inputBytes(),"Combined complete input bytes exceed declared capacity");originals.add(map("role",input.role(),"kind",input.kind(),"original",path.toString(),"captured","inputs/"+staged,"staged",staged,"identity",identity));
        }
        Files.createDirectory(root);String stage="CAPTURE_ORIGINAL_INPUTS";
        try {
            Files.createDirectory(root.resolve("inputs"));Files.createDirectory(root.resolve("sources"));Files.createDirectory(root.resolve("engine"));writeJson(root.resolve("INCOMPLETE.json"),map("analysis_admitted",false));
            writeJson(root.resolve("request.json"),spec.value());writeJson(root.resolve("source-inputs.json"),map("complete_original_bytes",true,"inputs",originals));
            Files.writeString(root.resolve("WARNINGS.md"),warnings(runtime.sourceMode()),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            for(var input:originals){Path from=Path.of(text(input.get("original"))),target=root.resolve(member(text(input.get("captured"))));if(input.get("kind").equals("meryl"))copyTree(from,target,spec,check);else Files.copy(from,target);}
            inputs(root,spec,originals,false,check);originals(spec,originals,check);
            writeJson(root.resolve("effective.json"),effective(spec,originals));
            MerquryProfile.copySource(runtime.source(),root.resolve("sources/merqury"),spec.edition(),runtime.sourceMode(),check);
            Files.write(root.resolve("sources/worker.py"),MerquryProfile.resource("worker.py"),StandardOpenOption.CREATE_NEW);Files.write(root.resolve("sources/decode.py"),MerquryProfile.resource("decode.py"),StandardOpenOption.CREATE_NEW);
            writeJson(root.resolve("runtime.json"),runtime.workerContext());writeJson(root.resolve("runtime-binding.json"),map("path",spec.runtime().toString(),"seal",runtime.seal(),"source_mode",runtime.sourceMode(),"edition",spec.edition()));
            NextflowProcess.Check integrity=()->{check.run();require(producer.equals(producer()),"Producer changed during Merqury execution");inputs(root,spec,originals,false,check);effectiveMatches(root,spec,originals);capturedHelpers(root,runtime);MerquryProfile.capturedSource(root.resolve("sources/merqury"),spec.edition(),runtime.sourceMode(),check);};
            stage="OWNED_ORIGINAL_WORKFLOW";
            NextflowProcess.executeSession(List.of(runtime.programs().get("python3"),"-I","-S","-B",root.resolve("sources/worker.py").toString(),root.toString()),runtime.executionEnvironment(),root.resolve("engine/process"),root,root,spec.process(),integrity,check);
            stage="COMPLETE_NUMERICAL_AND_BINARY_AUDIT";Path scratch=Files.createDirectory(root.resolve("inspection"));var audit=audit(root,scratch,spec,runtime,integrity,check);writeJson(root.resolve("OUTPUT-AUDIT.json"),audit);
            originals(spec,originals,check);runtime.verify(check);integrity.verify();stage="FINALIZE_COMPLETE_CAPTURE";
            var files=files(root,spec,check);files.remove("INCOMPLETE.json");writeJson(root.resolve("manifest.json"),map("schema_version",1,"producer",producer,"files",files,"analysis_admitted",true,"whole_package_admitted",false));
            writeJson(root.resolve("COMPLETED.json"),map("status","COMPLETE_MERQURY_SCOPED_WORKFLOW","manifest",pin(root.resolve("manifest.json"),134217728,check),"analysis_admitted",true,"whole_package_admitted",false));Files.delete(root.resolve("INCOMPLETE.json"));return root;
        }catch(IOException|RuntimeException|Error e){
            try{Files.deleteIfExists(root.resolve("COMPLETED.json"));if(!Files.exists(root.resolve("FAILURE.json")))writeJson(root.resolve("FAILURE.json"),map("status",e instanceof MerquryRuntime.Unavailable||e instanceof NextflowProcess.Unavailable?"SKIP3_DEPENDENT_MERQURY_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_MERQURY_WORKFLOW","stage",stage,"error",e.toString(),"analysis_admitted",false,"required_action",ACTION));}
            catch(IOException suppressed){e.addSuppressed(suppressed);}throw e;
        }
    }
    static void verify(Path supplied,Path suppliedScratch,Runnable cancellation)throws IOException {
        MerquryRuntime.platform();Path root=supplied.toAbsolutePath().normalize();directory(root);require(!Files.exists(root.resolve("INCOMPLETE.json"))&&!Files.exists(root.resolve("FAILURE.json"))&&!Files.exists(root.resolve("WORKER-FAILURE.json")),"Incomplete/failed Merqury capture refused");
        var done=object(json(root.resolve("COMPLETED.json"),1048576));require("COMPLETE_MERQURY_SCOPED_WORKFLOW".equals(done.get("status"))&&Boolean.TRUE.equals(done.get("analysis_admitted"))&&Boolean.FALSE.equals(done.get("whole_package_admitted")),"Complete scoped workflow admission required");
        Pin manifest=pin(root.resolve("manifest.json"),134217728,cancellation);require(manifest.equals(fingerprint(done.get("manifest"),134217728)),"Saved Merqury manifest changed");var m=object(json(root.resolve("manifest.json"),134217728));require(producer().equals(fingerprint(m.get("producer"),1000000000L)),"Restore exact producing Merqury JAR; do not refresh historical hashes");
        var spec=MerquryRequest.read(root.resolve("request.json"));Runnable check=bounded(spec,cancellation);inventory(root,spec,m.get("files"),check);var binding=object(json(root.resolve("runtime-binding.json"),1048576));require(spec.runtime().toString().equals(binding.get("path"))&&spec.edition().equals(binding.get("edition")),"Saved runtime binding identity differs");
        var runtime=MerquryRuntime.open(spec.runtime(),spec.edition(),check);require(runtime.seal().equals(fingerprint(binding.get("seal"),1048576))&&runtime.sourceMode().equals(binding.get("source_mode")),"Bound original runtime changed");
        require(Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warnings(runtime.sourceMode())),"Prominent warnings/actions changed");
        var sourceInputs=object(json(root.resolve("source-inputs.json"),16777216));keys(sourceInputs,"complete_original_bytes","inputs");require(Boolean.TRUE.equals(sourceInputs.get("complete_original_bytes")),"Incomplete original input provenance");
        var originals=new ArrayList<Map<String,Object>>();for(Object raw:list(sourceInputs.get("inputs"))){var row=new LinkedHashMap<String,Object>();object(raw).forEach((k,v)->row.put(k.toString(),v));originals.add(row);}inputs(root,spec,originals,false,check);effectiveMatches(root,spec,originals);
        MerquryProfile.capturedSource(root.resolve("sources/merqury"),spec.edition(),runtime.sourceMode(),check);capturedHelpers(root,runtime);
        Path scratch=suppliedScratch.toAbsolutePath().normalize();directory(scratch.getParent());require(!Files.exists(scratch)&&!scratch.startsWith(root)&&!root.startsWith(scratch),"Use a NEW scratch directory separate from immutable capture");Files.createDirectory(scratch);
        NextflowProcess.Check integrity=()->{inventory(root,spec,m.get("files"),check);require(manifest.equals(pin(root.resolve("manifest.json"),134217728,check)),"Capture changed during verification");};
        try {
            var audit=audit(root,scratch,spec,runtime,integrity,check);require(NextflowJson.json(audit).equals(NextflowJson.json(json(root.resolve("OUTPUT-AUDIT.json"),16777216))),"Saved complete numerical/binary audit differs");runtime.verify(check);integrity.verify();writeJson(scratch.resolve("VERIFIED.json"),map("status","PASS_COMPLETE_MERQURY_BINARY_AND_NUMERICAL_REPLAY","capture_manifest",manifest,"analysis_admitted",false,"new_scientific_analysis",false));
        }catch(IOException|RuntimeException|Error e){if(!Files.exists(scratch.resolve("FAILURE.json")))writeJson(scratch.resolve("FAILURE.json"),map("error",e.toString(),"analysis_admitted",false,"required_action",ACTION));throw e;}
    }
    private static Map<String,Object> audit(Path root,Path scratch,MerquryRequest.Spec spec,MerquryRuntime.Context runtime,NextflowProcess.Check integrity,Runnable check)throws IOException {
        // Decode opaque Meryl bytes afresh on EVERY admission and saved verification. No counts are rebuilt.
        NextflowProcess.executeSession(List.of(runtime.programs().get("python3"),"-I","-S","-B",root.resolve("sources/decode.py").toString(),root.toString(),scratch.toString()),runtime.executionEnvironment(),scratch.resolve("decoder-process"),scratch,scratch,spec.process(),integrity,check);
        var declarations=list(json(root.resolve("exports/DATABASES.json"),16777216));int number=0;
        for(Object value:declarations) {
            check.run();var row=object(value);Path saved=root.resolve(member(text(row.get("table")))),fresh=scratch.resolve(String.format(Locale.ROOT,"db-%04d.tsv",number++));
            MerquryTables.equalCounts(MerquryTables.counts(saved,spec.settings().k(),spec.capacity().outputBytes(),spec.capacity().distinctKmers(),check),MerquryTables.counts(fresh,spec.settings().k(),spec.capacity().outputBytes(),spec.capacity().distinctKmers(),check),"fresh original binary decoder "+row.get("database"));
        }
        Map<String,Object> numerical=spec.mode().equals("evaluate")?MerquryEvaluationAudit.run(root,spec,check):MerquryPreparationAudit.run(root,spec,check);
        Object cutoffs=runtime.sourceMode().equals(MerquryProfile.NATIVE)?MerquryCutoffs.replayNative(root,spec,check):MerquryCutoffs.replay(root,scratch.resolve("thresholds"),spec,Path.of(runtime.programs().get("java")),runtime.executionEnvironment(),integrity,check);
        Object tdf=spec.edition().equals("1.1")&&spec.mode().equals("evaluate")?MerquryTdf.replay(root,Files.createDirectory(scratch.resolve("tdf")),spec,runtime,integrity,check):List.of();
        return map("status","PASS_COMPLETE_MERQURY_SCOPED_WORKFLOW","mode",spec.mode(),"edition",spec.edition(),"source_mode",runtime.sourceMode(),"source_modified",!runtime.sourceMode().equals(MerquryProfile.ORIGINAL),"fresh_binary_databases",declarations.size(),"numerical",numerical,"cutoffs",cutoffs,"tdf",tdf,"whole_package_admitted",false);
    }
    private static String suffix(Path source)throws IOException {String name=source.getFileName().toString();for(String suffix:List.of(".fastq.gz",".fq.gz",".fasta.gz",".fa.gz",".fastq",".fq",".fasta",".fa"))if(name.endsWith(suffix))return suffix;throw new IOException("Count input requires explicit supported FASTA/FASTQ filename suffix");}
    private static Map<String,Object> effective(MerquryRequest.Spec spec,List<Map<String,Object>> originals) {
        var inputs=new ArrayList<Object>();for(var input:originals)inputs.add(map("role",input.get("role"),"kind",input.get("kind"),"captured",input.get("captured"),"staged",input.get("staged")));var s=spec.settings();
        return map("mode",spec.mode(),"edition",spec.edition(),"inputs",inputs,"settings",map("k",s.k(),"threads",s.threads(),"count_memory_gib",s.memoryGib(),"filter_parents",s.filterParents(),"false_duplications",s.falseDuplications()));
    }
    private static void effectiveMatches(Path root,MerquryRequest.Spec spec,List<Map<String,Object>> originals)throws IOException {require(NextflowJson.json(effective(spec,originals)).equals(NextflowJson.json(json(root.resolve("effective.json"),1048576))),"Effective original input population/settings differ from complete typed request");}
    private static void capturedHelpers(Path root,MerquryRuntime.Context runtime)throws IOException {for(String name:List.of("worker.py","decode.py")){byte[] value=MerquryProfile.resource(name);require(new Pin(value.length,sha(value)).equals(pin(root.resolve("sources/"+name),16777216,()->{})),"Saved exact workflow/decoder helper changed");}require(NextflowJson.json(runtime.workerContext()).equals(NextflowJson.json(json(root.resolve("runtime.json"),1048576))),"Captured original process environment differs");}
    private static void copyTree(Path from,Path to,MerquryRequest.Spec spec,Runnable check)throws IOException {directory(from);Files.createDirectory(to);for(var entry:tree(from,spec.capacity().files(),spec.capacity().inputBytes(),spec.capacity().inputBytes(),check).entrySet()){require(entry.getValue().kind().equals("file"),"Input database links refused");Path path=to.resolve(entry.getKey());Files.createDirectories(path.getParent());Files.copy(from.resolve(entry.getKey()),path);}}
    private static void originals(MerquryRequest.Spec spec,List<Map<String,Object>> rows,Runnable check)throws IOException {for(var row:rows)identity(Path.of(text(row.get("original"))),row,spec,check);}
    private static void inputs(Path root,MerquryRequest.Spec spec,List<Map<String,Object>> rows,boolean unused,Runnable check)throws IOException {require(rows.size()==spec.inputs().size(),"Complete original input role count differs");var names=new HashSet<String>();for(int i=0;i<rows.size();i++){var row=rows.get(i);keys(row,"role","kind","original","captured","staged","identity");var input=spec.inputs().get(i);String name=member(text(row.get("staged")));require(!name.contains("/")&&names.add(name)&&("inputs/"+name).equals(row.get("captured")),"Unexpected/repeated input staging identity");require(input.path().toString().equals(row.get("original"))&&input.role().equals(row.get("role"))&&input.kind().equals(row.get("kind")),"Saved original input roles/order differ");identity(root.resolve(member(text(row.get("captured")))),row,spec,check);}}
    private static void identity(Path path,Map<String,Object> row,MerquryRequest.Spec spec,Runnable check)throws IOException {if(row.get("kind").equals("meryl"))require(NextflowJson.json(manifest(tree(path,spec.capacity().files(),spec.capacity().inputBytes(),spec.capacity().inputBytes(),check))).equals(NextflowJson.json(row.get("identity"))),"Complete original Meryl input bytes changed");else require(pin(path,spec.capacity().inputBytes(),check).equals(fingerprint(row.get("identity"),spec.capacity().inputBytes())),"Complete original FASTX bytes changed");}
    static Map<String,Object> files(Path root,MerquryRequest.Spec spec,Runnable check)throws IOException {long total=Math.addExact(Math.addExact(spec.capacity().inputBytes(),spec.capacity().outputBytes()),268435456);return new TreeMap<>(manifest(tree(root,spec.capacity().files(),total,total,check)));}
    private static void inventory(Path root,MerquryRequest.Spec spec,Object expected,Runnable check)throws IOException {var actual=files(root,spec,check);actual.remove("manifest.json");actual.remove("COMPLETED.json");require(NextflowJson.json(actual).equals(NextflowJson.json(expected)),"Complete immutable Merqury capture namespace/bytes/links changed");}
    static String warnings(String mode){return "MERQURY: WARNINGS AND REQUIRED ACTION\n\nExplicit source mode: "+mode+". Native-boundary-palette-v1 modifies only the effective-depth helper call and plotting palette/legend. It consumes the same complete histogram and original first-valley equation, emits a separately named boundary TSV, and does not produce or repair the original full ploidy table. This is a deliberate native source profile, never an automatic fallback or an inferred author edition. Unchanged historical1.1/1.3 and current1.4.1 remain separate. Original helper formatting and Meryl lookup/plot failures remain failures.\n\nThe declared k and complete ordinary uncompressed k-mer databases must match the data and reference. Homopolymer compression is not inferred or supported by this profile. U and ambiguous IUPAC characters break k-mer windows; identifiers, duplicate records, multiplicities and complete input populations are retained. All native logical tables must fit declared memory/record/key capacities; no sampling, cropping, deduplication or parameter repair is used. Global QV weights missing k-mer OCCURRENCES. Completeness counts DISTINCT solid read k-mers above the automatic cutoff. False duplication uses the source copy-one peak and DISTINCT copy classes below1.5times the peak; absent source copy classes leave empty shell fields, so a requested undefined rate fails. Inf/NaN in defined source QV/completeness arithmetic remain labelled values and must not be interpreted as demonstrated perfect biological accuracy.\n\nMerqury1.1 hard-codes21-base BED intervals. Its complete TDF datasets/tiles/coordinates/names/values are decoded with original IGV2.19.8 and compared with deterministic coverage reconstruction from every independently validated BED interval and the full FASTA-checked FAI dictionary. Source NaN and zero-width summary bins remain visible in the retained complete semantics. Original1.3 Meryl lookup can fail with a nonsensical huge memory message and the shell may still exit0. Missing/empty per-sequence QV, BED/WIG or plot failures are independently detected. The selected current native profile uses unmodified Meryl1.4.1; it does not reproduce a historical paper edition. Parental k-mer construction is distinct from Verkko assembly and Yak phasing error analysis.\n\nEvery original process uses a private owned session with hard per-process AS/CPU/file/nofile limits, wall/workspace/process/thread checks and sampled aggregate RSS. Sampling is not a hard aggregate memory bound. Native audits use cooperative wall/cancellation checks. Full original/runtime inputs and all opaque database bytes are retained. Verification requires Linux and the exact producing JAR/runtime, performs fresh complete original binary decoding and repeats all native numerical checks without counting new reads or refitting models. Legacy TDF verification reconstructs deterministic coverage from the saved validated BED intervals. Hashes establish integrity, not authenticity or biological validity. Whole-package, whole-paper and biological reproduction are not admitted. Runtime binding is read-only; no analysis installs software or contacts a download service.\n\n"+ACTION+"\n";}
}
